operations.after:
  .os-scene-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.os-tool-tabs {
  display: flex;
  gap: 0.45rem;
  padding: 0.35rem;
  border: 1px solid var(--color-border-light-2, #6668);
  border-radius: 8px;
  background: rgb(0 0 0 / 18%);
}

.os-tool-tabs button {
  flex: 1 1 0;
  min-height: 2.35rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
}

.os-tool-tabs button.is-active {
  border-color: var(--color-border-highlight, #b78f55);
  background: rgb(255 255 255 / 8%);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 5%);
}

.os-comic-controls {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(150px, 0.8fr) minmax(190px, 1fr);
  gap: 0.6rem;
}

.os-comic-controls label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.os-comic-controls label > span {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  opacity: 0.75;
}

.os-comic-workspace {
  display: grid;
  grid-template-columns: minmax(270px, 0.95fr) minmax(310px, 1.05fr);
  gap: 0.85rem;
  align-items: start;
}

.os-comic-preview-wrap,
.os-comic-panel-editor {
  min-width: 0;
}

.os-comic-page-preview {
  position: relative;
  width: 100%;
  overflow: hidden;
  border: 1px solid rgb(0 0 0 / 80%);
  border-radius: 4px;
  background: #f4f0e6;
  box-shadow: 0 7px 22px rgb(0 0 0 / 34%);
}

.os-comic-preview-panel {
  position: absolute;
  box-sizing: border-box;
  margin: 0;
  overflow: hidden;
  border: 4px solid #080808;
  background: #111;
}

.os-comic-preview-panel img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.os-comic-preview-panel span {
  position: absolute;
  top: 0.35rem;
  left: 0.35rem;
  display: grid;
  place-items: center;
  min-width: 1.55rem;
  height: 1.55rem;
  padding: 0 0.3rem;
  border-radius: 999px;
  background: rgb(0 0 0 / 78%);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 800;
}

.os-comic-preview-wrap .hint {
  margin: 0.55rem 0 0;
  color: var(--color-text-light-6, #aaa);
  font-size: 0.78rem;
}

.os-comic-panel-editor {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.os-comic-dropzone {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.45rem;
  min-height: 5.5rem;
  padding: 0.8rem;
  border: 2px dashed var(--color-border-light-2, #777);
  border-radius: 8px;
  background: rgb(0 0 0 / 13%);
  text-align: center;
  transition: border-color 120ms ease, background 120ms ease;
}

.os-comic-dropzone > i {
  flex: 0 0 100%;
  font-size: 1.45rem;
  opacity: 0.8;
}

.os-comic-dropzone.is-dragging {
  border-color: var(--color-border-highlight, #b78f55);
  background: rgb(255 255 255 / 8%);
}

.os-comic-path-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.45rem;
}

.os-comic-warning {
  margin: 0;
  padding: 0.55rem 0.65rem;
  border: 1px solid rgb(210 80 70 / 55%);
  border-radius: 6px;
  background: rgb(140 30 24 / 18%);
  color: var(--color-level-error, #f88);
}

.os-comic-panel-list {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  max-height: 310px;
  overflow: auto;
}

.os-comic-panel-row {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr) auto;
  gap: 0.55rem;
  align-items: center;
  padding: 0.45rem;
  border: 1px solid var(--color-border-light-2, #6668);
  border-radius: 6px;
  background: rgb(0 0 0 / 15%);
}

.os-comic-panel-row > img {
  width: 76px;
  height: 54px;
  object-fit: cover;
  border: 2px solid #090909;
  border-radius: 3px;
}

.os-comic-panel-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.os-comic-panel-meta span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--color-text-light-6, #aaa);
  font-size: 0.75rem;
}

.os-comic-panel-actions {
  display: flex;
  gap: 0.25rem;
}

.os-comic-panel-actions button {
  min-width: 2rem;
  width: 2rem;
  height: 2rem;
  padding: 0;
}

.os-comic-panel-actions button.danger,
.os-comic-export-bar button.danger {
  color: var(--color-level-error, #f66);
}

.os-comic-empty {
  margin: 0;
  padding: 1rem;
  border: 1px dashed var(--color-border-light-2, #6668);
  border-radius: 6px;
  color: var(--color-text-light-6, #aaa);
  text-align: center;
}

.os-comic-export-bar {
  display: flex;
  justify-content: space-between;
  gap: 0.6rem;
  padding-top: 0.15rem;
}

.os-comic-export-bar .os-comic-export {
  flex: 1 1 auto;
  min-height: 2.5rem;
  font-weight: 700;
}

@media (max-width: 720px) {
  .os-comic-controls,
  .os-comic-workspace {
    grid-template-columns: 1fr;
  }

  .os-tool-tabs {
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .os-comic-path-row,
  .os-comic-panel-row {
    grid-template-columns: 1fr;
  }

  .os-comic-panel-row > img {
    width: 100%;
    height: 120px;
  }

  .os-comic-panel-actions {
    justify-content: flex-end;
  }
}
